// api.js — split from public/app.js
// All declarations remain on the global window scope. Do not import/export.
// Generated by scripts/split-frontend.js.

// ===== T-17 稳定性: 401 拦截 + AbortController + 并发限流 + debounce/throttle helper =====

// 当前活跃 AbortController 集合，离开视图时统一 abort()
const _activeAbortControllers = new Set();

// 并发上限（§9.1）
const _MAX_CONCURRENT_REQUESTS = 8;
let _inFlightCount = 0;
const _pendingQueue = [];
let _requestGeneration = 0;

// 用于 token 失效场景：先保草稿、再弹登录
let _isRedirecting401 = false;

async function _scheduleRequest(runner) {
  const generation = _requestGeneration;
  const abortIfStale = () => {
    if (generation !== _requestGeneration) {
      const err = new DOMException("Request cancelled", "AbortError");
      throw err;
    }
  };
  if (_inFlightCount < _MAX_CONCURRENT_REQUESTS) {
    _inFlightCount++;
    try {
      abortIfStale();
      return await runner();
    }
    finally {
      _inFlightCount--;
      const next = _pendingQueue.shift();
      if (next) next();
    }
  }
  // 排队等候
  return new Promise((resolve, reject) => {
    _pendingQueue.push(async () => {
      _inFlightCount++;
      try {
        abortIfStale();
        resolve(await runner());
      }
      catch (err) { reject(err); }
      finally {
        _inFlightCount--;
        const next = _pendingQueue.shift();
        if (next) next();
      }
    });
  });
}

// 401 处理：先保草稿（如果在录入页），再清 token，跳登录
async function _handle401() {
  if (_isRedirecting401) return;
  _isRedirecting401 = true;
  try {
    // 录入页若有未提交草稿，强制保一次（§9.1 第 4 条）
    if (typeof saveLeadDraftNow === "function" && state.currentView === "lead-entry" && state.leadDraftId) {
      try { await saveLeadDraftNow(); } catch {}
    }
  } finally {
    localStorage.removeItem("lan_system_token");
    if (typeof state !== "undefined") {
      state.token = "";
      state.user = null;
    }
    if (typeof setFlash === "function") {
      setFlash("warn", "登录已失效", "请重新登录后继续操作。已为您保存最近一次输入的草稿。");
    }
    if (typeof renderLogin === "function") {
      renderLogin();
    } else {
      window.location.reload();
    }
  }
}

async function api(path, options = {}) {
  return _scheduleRequest(async () => {
    const isFormData = options.body instanceof FormData;

    // T-17 AbortController：每个请求独立 signal，可被外部 abort
    let controller = null;
    if (!options.signal) {
      controller = new AbortController();
      _activeAbortControllers.add(controller);
    }
    const signal = options.signal || controller?.signal;

    try {
	      const response = await fetch(path, {
	        ...options,
	        signal,
	        headers: {
	          ...(state.token ? { Authorization: `Bearer ${state.token}` } : {}),
          ...(!isFormData ? { "Content-Type": "application/json" } : {}),
          ...(options.headers || {})
	        }
	      });

	      const refreshedToken = response.headers.get("X-New-Token");
	      if (refreshedToken) {
	        state.token = refreshedToken;
	        localStorage.setItem("lan_system_token", refreshedToken);
	      }

      // T-17 401 拦截：token 失效 → 保草稿 → 弹登录
      // 但要排除：
      //   1. 登录/注册等公共接口（密码错也会 401，但不是 "session expired"）
      //   2. 用户尚未登录的状态（避免登录页本身触发 redirect 死循环）
      if (response.status === 401) {
        const isAuthEndpoint = typeof path === "string" && /\/api\/auth\/(login|register)/.test(path);
        const hasSession = typeof state !== "undefined" && state.token && state.user;
        if (!isAuthEndpoint && hasSession) {
          await _handle401();
        }
        const data = await response.json().catch(() => ({ message: "认证失败" }));
        throw new Error(data.message || "认证失败");
      }

      if (!response.ok) {
        const data = await response.json().catch(() => ({ message: "请求失败" }));
        throw new Error(data.message || "请求失败");
      }
      return response.json();
    } finally {
      if (controller) _activeAbortControllers.delete(controller);
    }
  });
}

// 离开视图 / 切角色 / logout 时统一取消所有未完成请求
function abortAllPendingRequests() {
  _requestGeneration++;
  while (_pendingQueue.length) {
    const next = _pendingQueue.shift();
    if (next) {
      try { next(); } catch {}
    }
  }
  for (const ctrl of _activeAbortControllers) {
    try { ctrl.abort(); } catch {}
  }
  _activeAbortControllers.clear();
}

// ===== T-17 防双击 helper =====
// 包裹一个 async 处理函数，在执行期间锁住相同 key，避免重复触发
const _submittingKeys = new Set();
function withSubmitLock(key, asyncFn, lockMs = 1000) {
  return async function (...args) {
    if (_submittingKeys.has(key)) {
      if (typeof setFlash === "function") {
        setFlash("warn", "请稍候", "操作正在处理中，请勿重复点击。");
      }
      return;
    }
    _submittingKeys.add(key);
    setTimeout(() => _submittingKeys.delete(key), lockMs);
    try {
      return await asyncFn.apply(this, args);
    } finally {
      // 至少保留 lockMs ms 锁，防止表单连续提交
    }
  };
}

// ===== T-17 debounce / throttle helpers（供搜索框、看板筛选用） =====
function debounce(fn, wait = 300) {
  let timer = null;
  return function (...args) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), wait);
  };
}

function throttle(fn, wait = 300) {
  let last = 0;
  return function (...args) {
    const now = Date.now();
    if (now - last < wait) return;
    last = now;
    return fn.apply(this, args);
  };
}
